import{_ as t}from"./chunks/04.Ch-ZqWLj.js";import{_ as n}from"./chunks/02.DKb5XHsw.js";import{_ as r,o as s,c as l,j as a,a as e,aa as i}from"./chunks/framework.BAs_AphD.js";const d="/buildary-help-preview/academy/img/dalsi-zaznamy/07.webp",z="/buildary-help-preview/media/cs/diary/dalsi_volby_dalsizaznamy.png",m="/buildary-help-preview/media/cs/diary/reakce_na_zaznam.png",p="/buildary-help-preview/media/cs/diary/indikacni_ikony_dalsizaznamy.png",u="/buildary-help-preview/media/cs/diary/odeslat_zpravu.png",P=JSON.parse('{"title":"Další záznamy","description":"","frontmatter":{"title":"Další záznamy","wiki":"cs:diary:dailyentriesothers"},"headers":[],"relativePath":"diary/dailyentriesothers.md","filePath":"diary/dailyentriesothers.md","lastUpdated":1794209661000}'),k={name:"diary/dailyentriesothers.md"};function v(g,o,h,y,c,b){return s(),l("div",null,[...o[0]||(o[0]=[a("h1",{id:"dalsi-zaznamy",tabindex:"-1"},[e("Další záznamy "),a("a",{class:"header-anchor",href:"#dalsi-zaznamy","aria-label":'Permalink to "Další záznamy"'},"​")],-1),a("p",null,[e("Do sekce "),a("strong",null,"Další záznamy"),e(" zapisují oprávněné osoby výzvy, kontroly, předávky a připomínky – například stavbyvedoucí, technický dozor stavebníka nebo autorský dozor. Na záznam lze reagovat, poslat o něm e-mail, založit k němu úkol a každý Další záznam se podepisuje samostatně.")],-1),a("p",null,[e("Krok za krokem: "),a("a",{href:"/buildary-help-preview/akademie/dalsi-zaznamy"},"Zapsat výzvu, kontrolu nebo připomínku"),e(" a "),a("a",{href:"/buildary-help-preview/akademie/ukol-k-zaznamu"},"Založit úkol k zápisu v deníku"),e(" v Akademii.")],-1),a("div",{class:"video"},[a("iframe",{src:"https://www.youtube-nocookie.com/embed/0-e_jr07kEI",title:"Video: Další záznamy",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})],-1),i('<h2 id="zapsat-dalsi-zaznam" tabindex="-1">Zapsat Další záznam <a class="header-anchor" href="#zapsat-dalsi-zaznam" aria-label="Permalink to &quot;Zapsat Další záznam&quot;">​</a></h2><p>Záznamy mohou vkládat oprávněné osoby s kompetencí <strong>Další záznamy</strong>. V sekci klikněte na <strong>Přidat záznam</strong> – otevře se okno <strong>Přidání dalšího záznamu</strong>.</p><figure class="shot" style="--w:760px;"><img src="'+t+'" alt="Okno Přidání dalšího záznamu s rozbaleným seznamem kategorií" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Pole</th><th>Co do něj patří</th></tr></thead><tbody><tr><td><strong>Popis</strong></td><td>Text záznamu, libovolně dlouhý. Můžete ho nadiktovat tlačítkem <strong>Nadiktovat</strong>, nebo nechat vytvořit z fotografií tlačítkem <strong>Generovat pomocí AI</strong>.</td></tr><tr><td><strong>Název dodavatele</strong></td><td>Firma, které se záznam týká.</td></tr><tr><td><strong>Kategorie</strong></td><td>Druh záznamu, například <strong>Výzva ke kontrole zakrývaných prací</strong>, <strong>Předání a převzetí pracoviště</strong> nebo <strong>Technické kontroly, zkoušky a měření</strong>. Podle kategorie pak záznamy filtrujete.</td></tr><tr><td><strong>Upřesnění</strong></td><td>Bližší určení, třeba konstrukce nebo podlaží, kterého se záznam týká. Slouží také k filtrování.</td></tr><tr><td><strong>Přílohy k záznamu</strong></td><td>Fotografie a dokumenty.</td></tr></tbody></table><p>Seznam kategorií je číselník, který spravujete v nastavení stavby – viz <a href="/buildary-help-preview/diary/codelists">Číselníky deníku</a>.</p><p>Pokud jsou v <a href="/buildary-help-preview/diary/diarysettings">Nastavení deníku</a> zapnutá pole <strong>Poloha</strong> a <strong>Výkres</strong>, můžete záznam umístit do mapy nebo do výkresu stejně jako <a href="/buildary-help-preview/diary/dailyentriesworks">provedené práce</a>.</p><p>Pro přílohy platí stejná pravidla jako u provedených prací: nejvýše 30 MB na soubor a raději žádné archivy ZIP nebo RAR – viz <a href="/buildary-help-preview/diary/dailyentriesworks#prilohy">Přílohy</a>.</p><p>U každého Dalšího záznamu se zobrazí jeho autor a jeho role v deníku.</p><h3 id="sablona-pro-rucni-zapis" tabindex="-1">Šablona pro ruční zápis <a class="header-anchor" href="#sablona-pro-rucni-zapis" aria-label="Permalink to &quot;Šablona pro ruční zápis&quot;">​</a></h3><p>Tlačítka <strong>PDF šablona</strong> a <strong>Word šablona</strong> v záhlaví sekce stáhnou prázdný list s hlavičkou deníku. Hodí se pro záznamy, které se píšou a podepisují ručně – viz <a href="/buildary-help-preview/diary/signingwithout">Bez elektronického podpisu</a>.</p><h2 id="tlacitka-zaznamu" tabindex="-1">Tlačítka záznamu <a class="header-anchor" href="#tlacitka-zaznamu" aria-label="Permalink to &quot;Tlačítka záznamu&quot;">​</a></h2><p>V záhlaví záznamu jsou tlačítka <strong>Upravit</strong>, <strong>Podepsat</strong> a <strong>Reagovat</strong>, ostatní volby najdete v menu <strong>Další volby</strong> záznamu.</p><figure class="shot" style="--w:760px;"><img src="'+d+'" alt="Uložený Další záznam s tlačítky Upravit, Podepsat, Reagovat a Další volby" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Tlačítko nebo volba</th><th>K čemu slouží</th></tr></thead><tbody><tr><td><strong>Upravit</strong></td><td>Změní záznam. Smí jen autor, a to jen dokud záznam nepodepíše a dokud na něj nikdo nereagoval.</td></tr><tr><td><strong>Podepsat</strong></td><td>Podepíše a uzamkne záznam – viz <a href="#podpis-dalsiho-zaznamu">Podpis Dalšího záznamu</a>.</td></tr><tr><td><strong>Náhled záznamu</strong></td><td>Zobrazí záznam jako PDF.</td></tr><tr><td><strong>Reagovat</strong></td><td>Zapíše odpověď provázanou s tímto záznamem – viz <a href="#reagovat-na-zaznam">Reagovat na záznam</a>.</td></tr><tr><td><strong>Související záznamy</strong></td><td>Zobrazí celé vlákno – původní záznam a všechny reakce. Je aktivní, až když na záznam někdo zareaguje.</td></tr><tr><td><strong>Seznam adresátů zprávy</strong></td><td>Pošle e-mail o záznamu vybraným oprávněným osobám – viz <a href="#poslat-e-mail-o-zaznamu">Poslat e-mail o záznamu</a>.</td></tr><tr><td><strong>Vytvořit nový úkol pro tento záznam</strong></td><td>Založí úkol v Managementu úkolů – viz <a href="#ukol-k-zaznamu">Úkol k záznamu</a>.</td></tr><tr><td><strong>Úkoly pro tento záznam</strong></td><td>Zobrazí úkoly založené k záznamu.</td></tr><tr><td><strong>Smazat</strong></td><td>Smaže záznam. Smí jen autor, a to jen dokud záznam nepodepíše a dokud na něj nikdo nereagoval.</td></tr></tbody></table><p>Potřebujete smazat nepodepsaný záznam, na který už někdo reagoval? Nejdřív musí autor reakce smazat svou reakci, pak smažete záznam.</p><figure class="shot" style="--w:420px;"><img src="'+z+'" alt="Rozbalené menu Další volby u Dalšího záznamu" loading="lazy"></figure><h2 id="reagovat-na-zaznam" tabindex="-1">Reagovat na záznam <a class="header-anchor" href="#reagovat-na-zaznam" aria-label="Permalink to &quot;Reagovat na záznam&quot;">​</a></h2><p>Tlačítkem <strong>Reagovat</strong> otevřete okno <strong>Záznam, na který chcete reagovat</strong>. Nahoře vidíte původní záznam, pod ním vyplníte reakci:</p><ul><li><strong>Popis</strong> – text reakce.</li><li><strong>Název dodavatele</strong>, <strong>Kategorie</strong> a <strong>Upřesnění</strong> – převezmou se z původního záznamu, můžete je změnit.</li><li><strong>Datum, kam bude odpověď zapsána</strong> – předvyplní se dnešní datum. V kalendáři můžete vybrat i jiný den, aplikace ale nabídne jen dny, do kterých reakci zapsat lze: dny, které ještě nejsou podepsané, nejdříve však den původního záznamu.</li></ul><figure class="shot" style="--w:560px;"><img src="'+m+'" alt="Okno Záznam, na který chcete reagovat s výběrem data reakce" loading="lazy"></figure><p>Pod záznamem, na který někdo reagoval, se objeví žlutá ikona <strong>Související záznamy</strong> s počtem reakcí. Kliknutím na ni otevřete okno <strong>Vlákno reakcí na další záznam</strong> se všemi souvisejícími záznamy. Záznam, ze kterého jste vlákno otevřeli, má modré záhlaví.</p><figure class="shot" style="--w:560px;"><img src="'+p+'" alt="Ikony Umístění, Související záznamy a Seznam adresátů zprávy u Dalšího záznamu" loading="lazy"></figure><h2 id="poslat-e-mail-o-zaznamu" tabindex="-1">Poslat e-mail o záznamu <a class="header-anchor" href="#poslat-e-mail-o-zaznamu" aria-label="Permalink to &quot;Poslat e-mail o záznamu&quot;">​</a></h2><p>Další záznamy často čekají na rychlou odpověď druhé strany. Aby se o záznamu dotyčný včas dozvěděl, pošlete mu e-mail:</p><ol><li>V <strong>Dalších volbách</strong> záznamu zvolte <strong>Seznam adresátů zprávy</strong>.</li><li>V okně <strong>Další záznamy oznámení</strong> zaškrtněte adresáty a klikněte na <strong>Odeslat</strong>.</li></ol><p>V seznamu jsou všechny oprávněné osoby deníku. Rozbalením osoby uvidíte její e-mail a roli, u osob, kterým už oznámení odešlo, i datum a čas odeslání. Červený vykřičník označuje osoby, které jsou pozvané na stavbu, ale ještě nemají v Buildary účet. Oznámení můžete poslat i opakovaně.</p><figure class="shot" style="--w:420px;"><img src="'+u+'" alt="Okno Další záznamy oznámení se seznamem adresátů" loading="lazy"></figure><p>Odeslané oznámení poznáte podle fialové ikony <strong>Seznam adresátů zprávy</strong> u záznamu. Číslo udává, kolika lidem oznámení odešlo. Kliknutím na ikonu otevřete seznam adresátů – kdo e-mail dostal, má modrou obálku.</p><div class="tip custom-block"><p class="custom-block-title">Automatické oznámení</p><p>Oznámení o každém novém Dalším záznamu může chodit automaticky. U oprávněné osoby v <a href="/buildary-help-preview/diary/diaryidentification">Identifikačních údajích deníku</a> zaškrtněte <strong>E-mailové oznámení o přidání dalšího záznamu</strong>. Osoba musí mít v <a href="/buildary-help-preview/diary/projectteam">projektovém týmu</a> u e-mailového oznámení pro stavební deník nastaveno <strong>Dle nastavení deníku</strong>.</p></div><h2 id="ukol-k-zaznamu" tabindex="-1">Úkol k záznamu <a class="header-anchor" href="#ukol-k-zaznamu" aria-label="Permalink to &quot;Úkol k záznamu&quot;">​</a></h2><p>Když ze záznamu vyplývá konkrétní práce, založte k němu úkol. Úkol se uloží v <a href="/buildary-help-preview/tickets/">Managementu úkolů</a> a zůstane se záznamem propojený. Modul Management úkolů musí být na stavbě zapnutý.</p><p>Úkol lze založit u Dalších záznamů i u <a href="/buildary-help-preview/diary/dailyentriesworks">provedených prací</a>:</p><ul><li>U provedené práce klikněte v záhlaví záznamu na <strong>Vytvoř nový úkol pro tento záznam</strong>.</li><li>U Dalšího záznamu zvolte v <strong>Dalších volbách</strong> <strong>Vytvořit nový úkol pro tento záznam</strong>.</li></ul><p>Otevře se formulář <strong>Nový úkol</strong>. V jeho záhlaví vidíte, ke kterému záznamu se úkol váže (druh záznamu, datum, autor a popis). Vyplňte předmět a popis, nastavte prioritu a termíny a vyberte Řešitele a Schvalovatele. K jednomu záznamu můžete založit i více úkolů.</p><figure class="shot" style="--w:760px;"><img src="'+n+'" alt="Formulář Nový úkol propojený se záznamem z deníku" loading="lazy"></figure><p>Úkoly založené k Dalšímu záznamu zobrazíte v <strong>Dalších volbách</strong> volbou <strong>Úkoly pro tento záznam</strong>. Jak se s úkoly pracuje dál, popisuje <a href="/buildary-help-preview/tickets/">Management úkolů</a>.</p><h2 id="podpis-dalsiho-zaznamu" tabindex="-1">Podpis Dalšího záznamu <a class="header-anchor" href="#podpis-dalsiho-zaznamu" aria-label="Permalink to &quot;Podpis Dalšího záznamu&quot;">​</a></h2><p>Každý Další záznam se podepisuje samostatně, nezávisle na podpisu dne. Svůj záznam by měl autor podepsat a tím uzamknout – tlačítkem <strong>Podepsat</strong> u záznamu. Kdo nemá elektronický podpis, může záznam uzamknout nahraným skenem ručně podepsaného záznamu.</p><p>Způsoby podpisu a postup popisuje <a href="/buildary-help-preview/diary/signing">Podepisování deníku</a>, krok za krokem: <a href="/buildary-help-preview/akademie/podpis-dalsiho-zaznamu">Podepsat jednotlivý zápis</a> v Akademii.</p>',39)])])}const D=r(k,[["render",v]]);export{P as __pageData,D as default};
